import{_ as o,o as r,c as e,a3 as s}from"./chunks/framework.lx4Uzxpr.js";const p=JSON.parse('{"title":"编码器：位置反馈的真值来源","description":"编码器的内核是把机械角度变成信号；增量式数脉冲、绝对式读码，两者的全部差异都从\\"断电后还记不记得自己是谁\\"推出","frontmatter":{"title":"编码器：位置反馈的真值来源","date":"2026-10-24T00:00:00.000Z","tags":["机器人","硬件","传感器"],"category":"notes","description":"编码器的内核是把机械角度变成信号；增量式数脉冲、绝对式读码，两者的全部差异都从\\"断电后还记不记得自己是谁\\"推出","sidebar":false},"headers":[],"relativePath":"notes/机器人/硬件与电子/encoders.md","filePath":"notes/机器人/硬件与电子/encoders.md"}'),n={name:"notes/机器人/硬件与电子/encoders.md"};function a(l,t,i,g,c,d){return r(),e("div",null,t[0]||(t[0]=[s('<h1 id="编码器" tabindex="-1">编码器 <a class="header-anchor" href="#编码器" aria-label="Permalink to “编码器”">​</a></h1><p><strong>一句话定义：编码器 = 把机械角度转换为电信号的传感器；控制环、标定、测试里所有&quot;位置&quot;一词的可信度都来自它。</strong></p><h2 id="内核-为什么分增量式与绝对式" tabindex="-1">内核：为什么分增量式与绝对式 <a class="header-anchor" href="#内核-为什么分增量式与绝对式" aria-label="Permalink to “内核：为什么分增量式与绝对式”">​</a></h2><p>位置反馈有个根本分野：<strong>断电重启后，零位还在不在？</strong></p><ul><li><strong>增量式</strong>：码盘均匀刻线，转一圈输出 N 个脉冲 + 一条零位脉冲。控制器<strong>数脉冲</strong>得知相对位移——便宜、分辨率高，但断电即失忆，上电必须找零；丢一个脉冲（抖动/干扰）误差永久累积。</li><li><strong>绝对式</strong>：每个角度位置对应唯一码值（单圈）或唯一计数（多圈，电池/机械记圈）——上电即知位置，没有累积误差，代价是码盘复杂、价格高。</li></ul><p>由此推出一个容易记混的概念区分：<strong>分辨率 ≠ 精度</strong>。分辨率是能分辨的最小刻度（多少线/多少位），精度是读数与真实角度的偏差（受码盘安装偏心、细分误差影响）。标定算法再好，也超不过编码器精度这条天花板。</p><h2 id="规则与行为" tabindex="-1">规则与行为 <a class="header-anchor" href="#规则与行为" aria-label="Permalink to “规则与行为”">​</a></h2><p><strong>四倍频</strong>：增量式 A/B 两相正交（相差 90°），比较相位即知方向；对 A、B 的上升沿与下降沿都计数，分辨率 ×4——这是&quot;2000 线编码器输出 8000 计数/圈&quot;的来源。</p><p><strong>选型与使用规则</strong>：</p><ol><li><strong>控制环位置</strong>：电流环内不需要编码器（FOC 换相用的角度可低分辨率甚至无感估计），速度环用增量即可，<strong>位置环与安全相关处必须绝对式</strong>——机械臂断电不下坠、重启不需要找零，靠的就是多圈绝对值编码器。</li><li><strong>双编码器方案</strong>：关节模组常在电机端与输出端各放一个（后者在<a href="/notes/机器人/结构与机构/reducers" class="term-link" title="功率守恒下力矩换转速；背隙与刚度是它的两个性格参数">减速器</a>之后）。输出端编码器看到的是&quot;真实关节角&quot;（含背隙与柔轮形变），电机端看到的是&quot;转子角&quot;（换相必需、带宽高）。<strong>两者之差直接度量传动链误差</strong>——舵机测试里对比这两个读数是最有诊断价值的手段之一。</li><li><strong>时间戳纪律</strong>：编码器读数必须带采集时刻（见<a href="/notes/机器人/软件与中间件/time-sync-replay" class="term-link" title="时间戳在采集层打、全链路透传；录包把现场变成可重放数据">数据回放与时间同步</a>），位置环里用错时间戳的读数等效于引入速度噪声。</li></ol><h2 id="抽象-真值-角色" tabindex="-1">抽象：&quot;真值&quot;角色 <a class="header-anchor" href="#抽象-真值-角色" aria-label="Permalink to “抽象：&quot;真值&quot;角色”">​</a></h2><p>抽象后，编码器在系统里扮演三个角色：<strong>控制环的反馈</strong>、<strong>标定的基准</strong>（<a href="/notes/机器人/感知与估计/sensor-calibration" class="term-link" title="估计内参与外参使多源数据自洽；手眼标定 AX=XB">传感器标定</a>里手眼标定的 AX、XB 都由它驱动）、<strong>测试的裁判</strong>（指标里的&quot;到位精度&quot;以它为准）。一个务实的推论：<strong>做任何&quot;精度&quot;实验前，先问编码器的精度与安装方式</strong>——真值链上端的误差无法被下端修复。</p>',12)]))}const u=o(n,[["render",a]]);export{p as __pageData,u as default};
